export async function executeQuery(q: Query): Promise<unknown> {
  switch (q.command) {
    case 'read': return `Reading: ${q.args.join(', ')}`;
    case 'write': return `Writing: ${q.args.join(', ')}`;
    default: return `Unknown command: ${q.command}`;
  }
}
